"""CLF-C02 Domain 1 (Cloud Concepts) and Domain 2 (Security and Compliance)."""
from _awshelp import A, D, E, L, cfg, clab, qa
from builder import animation

T = "frontend/src/simulations/groups/aws.test.ts"
ids = lambda p, n: [f"CLFC02-{p}.{i}" for i in range(1, n + 1)]  # noqa: E731
animation("aws-concepts-sim", "Cloud concepts: Well-Architected, migration, CAF and economics", E, ids("1.1", 3) + ids("1.2", 3) + ids("1.3", 4) + ids("1.4", 8), "simplified-illustration", T,
          "Decision labs for Well-Architected pillars, the 7 Rs, CAF perspectives, plus a fixed-vs-variable cost model.")
animation("aws-security-sim", "Shared responsibility, IAM evaluation and security services", E, ids("2.1", 6) + ids("2.2", 9) + ids("2.3", 10) + ids("2.4", 6), "accurate-model", T,
          "Responsibility by service, IAM policy evaluation (SCP, explicit deny, allow, implicit deny), security service selection and root-only tasks.")

OV = D + "whitepapers/latest/aws-overview/introduction.html"
WA = D + "wellarchitected/latest/framework/welcome.html"
CAF = D + "whitepapers/latest/overview-aws-cloud-adoption-framework/welcome.html"
SR = A + "compliance/shared-responsibility-model/"
IAM = D + "IAM/latest/UserGuide/introduction.html"

# ---------------------------------------------------------------- 1.1
L(id="clf-benefits", title="Benefits of the AWS Cloud", objectives=ids("1.1", 3), minutes=25,
  objective="Explain the AWS Cloud value proposition and the benefits of its global infrastructure, high availability, elasticity and agility.",
  prereqs=["Basic IT concepts"],
  foundation=["AWS lets you use IT resources on demand over the internet and pay only for what you use, instead of buying and running data centers.", "Its global infrastructure lets you deploy in many locations worldwide in minutes, close to your users.",
              "High availability keeps applications running when parts fail; elasticity adds and removes capacity automatically; agility means teams can experiment and launch faster."],
  engineer=["AWS's six advantages of cloud computing: trade fixed expense for variable expense; benefit from massive economies of scale; stop guessing capacity; increase speed and agility; stop spending money running and maintaining data centers; go global in minutes.",
            "Global infrastructure: Regions with multiple isolated Availability Zones, plus edge locations for CloudFront, Route 53 and Global Accelerator; Local Zones and Wavelength Zones extend closer to users.",
            "High availability: design across multiple AZs with load balancing and Auto Scaling; elasticity: Auto Scaling matches capacity to demand; agility: provision in minutes and automate with IaC."],
  anim=("aws-concepts-sim", "Explore cloud economics and Well-Architected decisions."),
  diagram=([("r", "Region", 200, 0, "globe"), ("az1", "AZ a", 0, 120, "compute"), ("az2", "AZ b", 200, 120, "compute"), ("az3", "AZ c", 400, 120, "compute"), ("edge", "Edge locations (CloudFront)", 620, 0, "network")], [("r", "az1"), ("r", "az2"), ("r", "az3"), ("edge", "r", "caches")]),
  example=("Launching in a new country", ["A retailer launches in Japan by deploying its stack to the Tokyo Region with CloudFormation in an afternoon, uses Auto Scaling for the launch spike, and serves images from CloudFront edge locations."]),
  config=cfg(["AWS Management Console > Region selector: see available Regions.", "EC2 > Auto Scaling groups to see elasticity settings."], "aws ec2 describe-regions --output table\naws ec2 describe-availability-zones --region eu-west-1 --output table", "Get-EC2Region\nGet-EC2AvailabilityZone -Region eu-west-1"),
  lab=dict(type="A", objective="Compare fixed and variable cost models.", duration=10, steps=["Open 'Cloud economics' and run it.", "Apply 'Rightsize and automate'."], expected=["Variable costs track use"], validation=[("aws-economics", "Compared costs"), ("aws-rightsized", "Applied rightsizing")], failures=["Buying for peak"]),
  troubleshooting=[("Users far away see slow responses.", "Content served from one distant Region.", "Use CloudFront or deploy to a nearer Region."), ("Paying for idle servers.", "No elasticity.", "Use Auto Scaling and rightsizing.")],
  comparisons=[("Microsoft Azure", "Same benefits; regions/zones and CDN (Front Door) are equivalent concepts.")],
  misconceptions=[("Elasticity and high availability are the same.", "Elasticity matches capacity to demand; HA survives failures."), ("Going global requires building data centers.", "Deploy to existing Regions in minutes.")],
  decisions=["Deploy across multiple AZs by default; add Regions for latency, DR or data residency."],
  docs=[("Overview of Amazon Web Services: six advantages", D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html"), ("AWS global infrastructure", A + "about-aws/global-infrastructure/"), ("What is cloud computing?", A + "what-is-cloud-computing/")])
qa("CLFC02-1.1.1", 1, "single", "Which is one of the advantages of cloud computing described by AWS?", [("Trade fixed expense for variable expense", "Correct."), ("Guarantee zero downtime", "No guarantee of zero downtime."), ("Eliminate all security responsibilities", "Shared responsibility still applies."), ("Require long-term hardware contracts", "The opposite.")], "a", "Six advantages include variable expense and economies of scale.", D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html")
qa("CLFC02-1.1.1", 2, "scenario", "A company keeps buying too many servers because it cannot predict demand. Which cloud advantage addresses this?", [("Stop guessing capacity", "Correct."), ("Go global in minutes", "About reach."), ("Economies of scale", "About price."), ("Stop spending on data centers", "Related, but capacity guessing is the direct fit.")], "a", "Scale up or down as needed.", D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html")
qa("CLFC02-1.1.2", 1, "single", "What does the AWS global infrastructure let customers do?", [("Deploy applications in multiple geographic locations within minutes", "Correct."), ("Choose specific data center buildings", "Customers choose Regions/AZs."), ("Avoid all latency", "Latency is reduced, not eliminated."), ("Run only in the US", "No.")], "a", "Speed of deployment and global reach.", A + "about-aws/global-infrastructure/")
qa("CLFC02-1.1.2", 2, "scenario", "A game company wants low latency for players in Europe and Asia. What global-infrastructure benefit helps?", [("Deploy in Regions close to players and use edge locations", "Correct."), ("Use one Region and bigger instances", "Distance still adds latency."), ("Use AWS Artifact", "Compliance reports."), ("Buy Reserved Instances", "Pricing.")], "a", "Proximity reduces latency.", A + "about-aws/global-infrastructure/")
qa("CLFC02-1.1.3", 1, "single", "Which describes elasticity?", [("Automatically acquiring and releasing resources as demand changes", "Correct."), ("Keeping a fixed number of servers", "No."), ("Running in two Regions", "DR/HA."), ("Encrypting data", "Security.")], "a", "Auto Scaling provides elasticity.", A + "what-is-cloud-computing/")
qa("CLFC02-1.1.3", 2, "scenario", "Developers want to try a new feature on new infrastructure today and delete it tomorrow if it fails. Which benefit is this?", [("Agility", "Correct."), ("High availability", "Uptime."), ("Economies of scale", "Pricing."), ("Data sovereignty", "Location of data.")], "a", "Fast, low-cost experimentation.", D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html")

# ---------------------------------------------------------------- 1.2
L(id="clf-well-architected", title="AWS Well-Architected Framework", objectives=ids("1.2", 3), minutes=30,
  objective="Describe the Well-Architected Framework and its six pillars, and tell the pillars apart.",
  prereqs=[("Cloud benefits", "CLFC02-1.1.1", "clf-benefits")],
  foundation=["The Well-Architected Framework is AWS's set of best practices for designing and running workloads in the cloud.", "It has six pillars: operational excellence, security, reliability, performance efficiency, cost optimization and sustainability.",
              "The free AWS Well-Architected Tool lets you review a workload against these best practices."],
  engineer=["Operational excellence: perform operations as code, make frequent small reversible changes, refine procedures, anticipate failure, learn from operational events.",
            "Security: strong identity foundation, traceability, security at all layers, automate security best practices, protect data in transit and at rest, keep people away from data, prepare for security events.",
            "Reliability: automatically recover from failure, test recovery procedures, scale horizontally, stop guessing capacity, manage change through automation.",
            "Performance efficiency: democratise advanced technologies, go global in minutes, use serverless architectures, experiment more often, consider mechanical sympathy.",
            "Cost optimization: implement cloud financial management, adopt a consumption model, measure overall efficiency, stop spending on undifferentiated heavy lifting, analyse and attribute expenditure.",
            "Sustainability: understand your impact, establish goals, maximise utilisation, adopt more efficient hardware and software, use managed services, reduce downstream impact."],
  anim=("aws-concepts-sim", "Open 'Well-Architected pillars' and match concerns to pillars."),
  diagram=([("wa", "Well-Architected Framework", 300, 0, "service")] + [(f"p{i}", n, i * 150 - 75, 130, "security") for i, n in enumerate(["Operational excellence", "Security", "Reliability", "Performance efficiency", "Cost optimization", "Sustainability"], start=1)], [("wa", f"p{i}") for i in range(1, 7)]),
  example=("A review before launch", ["Before launching, a team runs a Well-Architected review in the Well-Architected Tool. It finds single-AZ databases (reliability), no MFA on admin users (security) and oversized instances (cost), and fixes them."]),
  config=cfg(["AWS Well-Architected Tool > Define workload > Start review."], "aws wellarchitected list-workloads", "Get-WATWorkloadList"),
  lab=clab("aws-pillar", "Well-Architected pillars", "pillar"),
  troubleshooting=[("Outages when one AZ fails.", "Reliability gaps.", "Apply reliability-pillar practices (multi-AZ, automatic recovery)."), ("Costs keep rising.", "No cost-optimization practices.", "Rightsize, adopt the consumption model, attribute spend.")],
  comparisons=[("Azure Well-Architected Framework", "Five pillars (reliability, security, cost optimization, operational excellence, performance efficiency); AWS adds sustainability as a sixth pillar.")],
  misconceptions=[("Performance efficiency is about cost.", "It is about using resources efficiently to meet requirements; cost has its own pillar."), ("The framework is a paid service.", "The framework and the Well-Architected Tool are free.")],
  decisions=["Review workloads regularly, not only before launch."],
  docs=[("AWS Well-Architected Framework", WA), ("The pillars of the framework", D + "wellarchitected/latest/framework/the-pillars-of-the-framework.html"), ("AWS Well-Architected Tool", D + "wellarchitected/latest/userguide/intro.html")])
qa("CLFC02-1.2.1", 1, "single", "What is the AWS Well-Architected Framework?", [("A set of best practices and questions for designing and operating reliable, secure, efficient, cost-effective and sustainable workloads", "Correct."), ("A billing tool", "No."), ("A managed database", "No."), ("A compliance report", "No.")], "a", "It guides architecture reviews.", WA)
qa("CLFC02-1.2.1", 2, "scenario", "A team wants a free, structured review of its workload against AWS best practices. What should it use?", [("AWS Well-Architected Tool", "Correct."), ("AWS Artifact", "Compliance reports."), ("AWS Pricing Calculator", "Estimates."), ("Amazon Inspector", "Vulnerability scanning.")], "a", "The Well-Architected Tool is in the console.", D + "wellarchitected/latest/userguide/intro.html")
qa("CLFC02-1.2.2", 1, "single", "How many pillars does the Well-Architected Framework have?", [("Six", "Correct."), ("Four", "No."), ("Five", "Azure's framework has five; AWS added sustainability."), ("Seven", "No.")], "a", "Operational excellence, security, reliability, performance efficiency, cost optimization, sustainability.", D + "wellarchitected/latest/framework/the-pillars-of-the-framework.html")
qa("CLFC02-1.2.2", 2, "scenario", "Which pillar includes the design principle 'perform operations as code'?", [("Operational excellence", "Correct."), ("Security", "No."), ("Reliability", "No."), ("Sustainability", "No.")], "a", "Operations as code reduces human error.", D + "wellarchitected/latest/operational-excellence-pillar/welcome.html")
qa("CLFC02-1.2.3", 2, "scenario", "A company deploys across multiple AZs and tests failover regularly. Which pillar does this mainly address?", [("Reliability", "Correct."), ("Performance efficiency", "Not the main goal."), ("Cost optimization", "No."), ("Operational excellence", "Related, but multi-AZ recovery is reliability.")], "a", "Reliability: recover from failure, test recovery.", D + "wellarchitected/latest/reliability-pillar/welcome.html")
qa("CLFC02-1.2.3", 2, "scenario", "Choosing Graviton instances and managed services to maximise utilisation and reduce energy use maps mainly to which pillar?", [("Sustainability", "Correct."), ("Security", "No."), ("Reliability", "No."), ("Operational excellence", "No.")], "a", "Sustainability focuses on environmental impact.", D + "wellarchitected/latest/sustainability-pillar/sustainability-pillar.html")

# ---------------------------------------------------------------- 1.3
L(id="clf-migration", title="Migrating to AWS: CAF, adoption strategies and migration resources", objectives=ids("1.3", 4), minutes=35,
  objective="Describe the AWS Cloud Adoption Framework perspectives and outcomes, cloud adoption and migration strategies, and the resources that support migration.",
  prereqs=[("Cloud benefits", "CLFC02-1.1.1", "clf-benefits")],
  foundation=["The AWS Cloud Adoption Framework (AWS CAF) organises guidance into six perspectives so an organisation can plan its move to the cloud: Business, People, Governance, Platform, Security and Operations.",
              "Migration strategies (the '7 Rs') describe what to do with each application: rehost, replatform, refactor, repurchase, retire, retain or relocate.", "AWS provides tools, programs and partners to help, such as AWS Migration Hub, Application Migration Service, DMS and Migration Evaluator."],
  engineer=["CAF business outcomes: reduced business risk, improved ESG (environmental, social and governance) performance, increased revenue and increased operational efficiency. Transformation domains: technology, process, organisation, product.",
            "Perspectives: Business (strategy, portfolio, innovation), People (culture, workforce, change), Governance (program/portfolio, risk, cloud financial management), Platform (architecture, engineering, CI/CD), Security (identity, detection, data protection, incident response), Operations (observability, incident and problem management).",
            "7 Rs: Rehost (lift and shift, often with AWS Application Migration Service), Replatform (for example to Amazon RDS), Refactor/re-architect (cloud-native), Repurchase (move to SaaS), Retire, Retain, Relocate (for example VMware Cloud on AWS).",
            "Migration resources: AWS Migration Hub (track migrations), AWS Application Discovery Service and Migration Evaluator (discovery and business case), AWS Application Migration Service (rehost servers), AWS DMS with SCT (database migration including ongoing replication), AWS Snow Family and DataSync (data transfer), AWS Prescriptive Guidance, AWS Professional Services and partners, and the Migration Acceleration Program (MAP)."],
  anim=("aws-concepts-sim", "Open 'Migration strategies' and 'Cloud Adoption Framework'."),
  diagram=([("disc", "Discover & assess (Migration Evaluator, ADS)", 0, 60, "service"), ("plan", "Plan with CAF perspectives", 230, 60, "user"), ("mig", "Migrate (MGN, DMS, Snow, DataSync)", 460, 60, "compute"), ("hub", "Track in Migration Hub", 690, 60, "service")], [("disc", "plan"), ("plan", "mig"), ("mig", "hub")]),
  example=("A data center exit", ["A company must leave its data center in a year. Migration Evaluator builds the business case, Application Migration Service rehosts 300 VMs, DMS replicates the Oracle databases to Aurora with minimal downtime (SCT converts schemas), and old reporting apps are retired."]),
  config=cfg(["AWS Migration Hub > Discover / Assess / Migrate.", "AWS DMS > Create replication instance and task."], "aws mgn describe-source-servers\naws dms describe-replication-tasks", "Get-DMSReplicationTask"),
  lab=clab("aws-migration", "Migration strategies", "migration strategy"),
  troubleshooting=[("Migration stalls on organisational resistance.", "People perspective ignored.", "Invest in training and change management."), ("Database migration needs near-zero downtime.", "Bulk copy only.", "Use DMS with ongoing replication (change data capture).")],
  comparisons=[("Microsoft Cloud Adoption Framework / Azure Migrate", "Equivalent frameworks and tools on Azure.")],
  misconceptions=[("Every app should be refactored.", "Choose per app; rehost is often first."), ("CAF is a migration tool.", "It is a framework of guidance.")],
  decisions=["Prioritise by business value and complexity; use rehost for speed and refactor where it pays off."],
  docs=[("Overview of the AWS CAF", CAF), ("Migration strategies (7 Rs)", D + "prescriptive-guidance/latest/large-migration-guide/migration-strategies.html"), ("AWS Migration Hub", D + "migrationhub/latest/ug/whatishub.html"), ("AWS Application Migration Service", D + "mgn/latest/ug/what-is-application-migration-service.html"), ("AWS DMS", D + "dms/latest/userguide/Welcome.html")])
qa("CLFC02-1.3.1", 1, "single", "Which migration strategy moves an application to AWS without changes?", [("Rehost", "Correct."), ("Refactor", "Re-architects."), ("Repurchase", "Moves to SaaS."), ("Retire", "Decommissions.")], "a", "Lift and shift.", D + "prescriptive-guidance/latest/large-migration-guide/migration-strategies.html")
qa("CLFC02-1.3.1", 2, "scenario", "A company replaces its on-premises email server with a SaaS email product. Which strategy is this?", [("Repurchase", "Correct."), ("Rehost", "No."), ("Replatform", "No."), ("Retain", "No.")], "a", "Drop and shop.", D + "prescriptive-guidance/latest/large-migration-guide/migration-strategies.html")
qa("CLFC02-1.3.2", 1, "single", "Which service tracks the progress of application migrations across multiple tools?", [("AWS Migration Hub", "Correct."), ("AWS Artifact", "Compliance."), ("Amazon Inspector", "Security."), ("AWS Budgets", "Costs.")], "a", "Central migration tracking.", D + "migrationhub/latest/ug/whatishub.html")
qa("CLFC02-1.3.2", 2, "scenario", "Leadership wants a data-driven business case showing projected AWS costs for on-premises servers. Which resource helps?", [("Migration Evaluator", "Correct."), ("AWS Shield", "No."), ("Amazon Macie", "No."), ("AWS X-Ray", "No.")], "a", "Migration Evaluator builds business cases from usage data.", A + "migration-evaluator/")
qa("CLFC02-1.3.3", 1, "single", "Which is an AWS CAF perspective?", [("People", "Correct."), ("Networking", "Not a perspective."), ("Billing", "No."), ("Storage", "No.")], "a", "Business, People, Governance, Platform, Security, Operations.", CAF)
qa("CLFC02-1.3.3", 2, "scenario", "Which business outcome of cloud adoption does the AWS CAF list?", [("Improved environmental, social and governance (ESG) performance", "Correct."), ("Guaranteed revenue doubling", "No."), ("Elimination of all IT staff", "No."), ("Unlimited free compute", "No.")], "a", "Outcomes: reduced business risk, improved ESG, increased revenue, increased operational efficiency.", CAF)
qa("CLFC02-1.3.4", 2, "scenario", "A database must be migrated with minimal downtime while the source stays in use. What should you use?", [("AWS DMS with ongoing replication", "Correct."), ("AWS Snowball only", "Offline bulk copy."), ("AWS Artifact", "No."), ("Amazon CloudFront", "No.")], "a", "DMS supports continuous replication until cutover.", D + "dms/latest/userguide/Welcome.html")
qa("CLFC02-1.3.4", 2, "scenario", "An app moves to EC2 but its self-managed MySQL is moved to Amazon RDS. Which strategy?", [("Replatform", "Correct."), ("Rehost", "No changes at all."), ("Refactor", "Re-architecting."), ("Relocate", "VMware hypervisor-level move.")], "a", "Lift, tinker and shift.", D + "prescriptive-guidance/latest/large-migration-guide/migration-strategies.html")

# ---------------------------------------------------------------- 1.4
L(id="clf-economics", title="Cloud economics", objectives=ids("1.4", 8), minutes=35,
  objective="Explain fixed vs variable costs, on-premises cost components, licensing strategies, rightsizing, automation and economies of scale.",
  prereqs=[("Cloud benefits", "CLFC02-1.1.1", "clf-benefits")],
  foundation=["On-premises IT has big fixed costs: you buy servers, space, power and staff up front, whether you use them or not.", "In AWS you mostly pay variable costs that rise and fall with use.",
              "You save more by choosing the right size of resources (rightsizing), automating tasks, and benefiting from AWS's huge scale, which lowers prices."],
  engineer=["Fixed vs variable: capital expenditure (CapEx) for hardware vs operational expenditure (OpEx) for consumption. Variable cost reduces waste from over-provisioning.",
            "On-premises costs (total cost of ownership): servers, storage, network gear, data center space, power and cooling, software licences, hardware maintenance, refresh cycles and staff time.",
            "Licensing: license-included (cost in the hourly price, for example Windows or SQL Server on EC2/RDS) vs Bring Your Own License (BYOL), which may require Dedicated Hosts for some licence terms; AWS License Manager tracks usage.",
            "Rightsizing: match instance types and sizes to measured utilisation (AWS Compute Optimizer, Cost Explorer rightsizing recommendations).",
            "Automation: IaC, scheduling start/stop, Auto Scaling and managed services reduce labour and errors.",
            "Economies of scale: AWS's aggregated usage lowers per-unit costs, passed on as lower prices."],
  anim=("aws-concepts-sim", "Open 'Cloud economics' and compare TCO with rightsizing, automation and BYOL."),
  diagram=([("onp", "On-prem fixed costs: hardware, space, power, staff", 0, 60, "compute"), ("aws", "AWS variable costs", 300, 60, "globe"), ("opt", "Rightsize + automate", 560, 60, "service")], [("onp", "aws", "migrate"), ("aws", "opt", "optimise")]),
  example=("Cutting idle capacity", ["A company's servers average 15% CPU. After migrating, Compute Optimizer recommendations rightsize most instances and dev environments are stopped nights and weekends by automation, reducing compute spend substantially compared with the on-premises estate."]),
  config=cfg(["AWS Compute Optimizer > Recommendations.", "Cost Explorer > Rightsizing recommendations.", "AWS License Manager > Licence configurations."], "aws compute-optimizer get-ec2-instance-recommendations\naws ce get-rightsizing-recommendation --service AmazonEC2", "Get-COEC2InstanceRecommendation"),
  lab=dict(type="A", objective="See how fixed costs, rightsizing, automation and licensing change total cost.", duration=10, steps=["Run 'Cloud economics' with defaults.", "Enable rightsizing and automation; switch licensing."], expected=["Variable, rightsized costs are lower"], validation=[("aws-economics", "Compared cost models"), ("aws-rightsized", "Rightsized")], failures=["Lift-and-shift without rightsizing"]),
  troubleshooting=[("Cloud bill higher than on-premises.", "Over-sized, always-on resources.", "Rightsize, schedule, use commitments for steady usage.")],
  comparisons=[("Azure Hybrid Benefit", "Azure's licensing benefit, comparable to BYOL on AWS.")],
  misconceptions=[("The cloud is always cheaper with no changes.", "Savings come from rightsizing, elasticity and automation."), ("BYOL is always cheaper.", "Depends on licence terms and possible Dedicated Host requirements.")],
  decisions=["Measure utilisation before and after migration; automate scheduling of non-production."],
  docs=[("Cloud economics", A + "economics/"), ("AWS Compute Optimizer", D + "compute-optimizer/latest/ug/what-is-compute-optimizer.html"), ("AWS License Manager", D + "license-manager/latest/userguide/license-manager.html"), ("Six advantages of cloud computing", D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html")])
for obj, s1, o1, s2, o2, doc in [
    ("1.4.1", "Which is an aspect of cloud economics?", [("Paying for resources as they are consumed (variable cost)", "Correct."), ("Buying hardware for peak demand", "On-premises model."), ("Fixed multi-year hardware refresh", "On-premises."), ("Higher per-unit cost with scale", "The opposite.")],
     "A company compares the total cost of running workloads on-premises with AWS, including staff and facilities. What is this analysis called?", [("Total cost of ownership (TCO) analysis", "Correct."), ("Rightsizing", "Optimisation of size."), ("Well-Architected review", "Architecture."), ("Shared responsibility", "Security.")], A + "economics/"),
    ("1.4.2", "Which cost is eliminated or reduced by moving to AWS?", [("Data center space, power and cooling", "Correct."), ("Application licence costs in all cases", "Not always."), ("All staff costs", "Staff still needed."), ("Data transfer costs", "Still charged.")],
     "A company retires its data center after migrating. Which savings does it gain?", [("No more spending on facilities and hardware refresh cycles", "Correct."), ("Free outbound data transfer", "Still charged."), ("No need for security", "Shared responsibility."), ("No need for backups", "Still required.")], A + "economics/"),
    ("1.4.3", "Which is a fixed cost?", [("Purchasing servers up front", "Correct."), ("On-Demand EC2 hours", "Variable."), ("S3 GB-months", "Variable."), ("Lambda requests", "Variable.")],
     "Traffic varies 10× between day and night. Which cost model avoids paying for idle capacity at night?", [("Variable cost with Auto Scaling", "Correct."), ("Fixed capacity sized for peak", "Idle at night."), ("Three-year hardware lease", "Fixed."), ("Dedicated Hosts", "Fixed per host.")], D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html"),
    ("1.4.4", "Which cost is associated with on-premises environments?", [("Hardware maintenance and replacement", "Correct."), ("AWS Support plan fees", "AWS."), ("S3 request charges", "AWS."), ("CloudFront data transfer", "AWS.")],
     "When estimating on-premises costs for a business case, which item is often overlooked?", [("Staff time to rack, patch and maintain hardware", "Correct."), ("AWS Regions", "No."), ("IAM users", "No."), ("Edge locations", "No.")], A + "economics/"),
    ("1.4.5", "What is Bring Your Own License (BYOL)?", [("Using existing software licences on AWS instead of paying for license-included instances", "Correct."), ("Getting free licences from AWS", "No."), ("Buying licences from AWS Marketplace only", "Different."), ("A Savings Plan", "Pricing model.")],
     "A company has Windows Server licences whose terms require dedicated physical servers. What should it use?", [("BYOL on Amazon EC2 Dedicated Hosts", "Correct."), ("License-included Spot Instances", "Does not reuse licences."), ("AWS Lambda", "No Windows Server licence model."), ("Amazon Lightsail", "No dedicated hosts.")], D + "AWSEC2/latest/UserGuide/dedicated-hosts-overview.html"),
    ("1.4.6", "What is rightsizing?", [("Matching instance types and sizes to workload performance and capacity needs at the lowest cost", "Correct."), ("Buying the largest instances", "No."), ("Choosing a Region", "No."), ("Encrypting volumes", "No.")],
     "Instances average 8% CPU for months. Which tool recommends smaller sizes?", [("AWS Compute Optimizer", "Correct."), ("AWS Artifact", "No."), ("AWS Shield", "No."), ("Amazon Macie", "No.")], D + "compute-optimizer/latest/ug/what-is-compute-optimizer.html"),
    ("1.4.7", "Which is a benefit of automation in the cloud?", [("Fewer manual errors and lower operational cost", "Correct."), ("Higher hardware costs", "No."), ("Longer deployment times", "No."), ("Removing the need for monitoring", "No.")],
     "Dev instances run 24/7 but are used only in office hours. What saves the most effort and cost?", [("Automate a start/stop schedule", "Correct."), ("Buy Reserved Instances for them", "Commits to 24/7 cost."), ("Move them to Dedicated Hosts", "More expensive."), ("Leave them running", "Waste.")], A + "economics/"),
    ("1.4.8", "What do economies of scale mean for AWS customers?", [("Lower variable costs because AWS aggregates usage from many customers", "Correct."), ("Customers must buy in bulk", "No."), ("Prices always increase", "No."), ("Only large companies get discounts", "No.")],
     "Why can AWS often offer lower prices than a single company running its own data center?", [("AWS spreads infrastructure costs across hundreds of thousands of customers", "Correct."), ("AWS uses no hardware", "No."), ("AWS has no staff", "No."), ("Customers manage AWS data centers", "No.")], D + "whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html"),
]:
    qa(f"CLFC02-{obj}", 1, "single", s1, o1, "a", o1[0][1] if o1[0][1] != "Correct." else "See the lesson.", doc)
    qa(f"CLFC02-{obj}", 2, "scenario", s2, o2, "a", "Applied cloud economics.", doc)

# ---------------------------------------------------------------- 2.1
L(id="clf-shared-responsibility", title="AWS shared responsibility model", objectives=ids("2.1", 6), minutes=30,
  objective="Describe AWS's responsibilities, the customer's responsibilities, shared controls, and how the split changes between EC2, RDS, Lambda and S3.",
  prereqs=[("Cloud benefits", "CLFC02-1.1.1", "clf-benefits")],
  foundation=["AWS is responsible for security OF the cloud: the hardware, software, networking and facilities that run AWS services.", "You are responsible for security IN the cloud: your data, who can access it, and how you configure services.",
              "The more managed the service, the more AWS takes on. With EC2 you patch the operating system; with RDS and Lambda, AWS does."],
  engineer=["AWS: physical security of data centers, hardware, global network, hypervisor and the software that runs managed services.",
            "Customer: customer data, platform/application/identity and access management, OS/network/firewall configuration (for EC2), client-side and server-side encryption choices, network traffic protection.",
            "Shared controls: patch management (AWS patches infrastructure, customer patches guest OS/apps), configuration management, awareness and training (AWS trains its staff, customers train theirs).",
            "By service: EC2 (IaaS): customer manages guest OS, apps, security groups and data. RDS: AWS manages OS and database engine patching, backups infrastructure; customer manages database users, network access, data and encryption settings. Lambda: AWS manages runtime and OS; customer manages code, permissions and data. S3: customer manages bucket policies, Block Public Access, encryption options and data."],
  anim=("aws-security-sim", "Open 'Shared responsibility by service' and assign tasks."),
  diagram=([("aws", "AWS: security OF the cloud (facilities, hardware, network, hypervisor)", 220, 160, "security"), ("cust", "Customer: security IN the cloud (data, IAM, configuration, OS on EC2)", 220, 0, "user")], [("cust", "aws", "builds on")]),
  example=("Same app, different split", ["On EC2, the team patches Amazon Linux monthly. After moving the database to RDS, AWS patches the database engine during the maintenance window, but the team still manages database users, security groups and encryption."]),
  config=cfg(["EC2 > Instances: you manage the OS (Systems Manager Patch Manager).", "RDS > Maintenance window: AWS-managed engine patching.", "S3 > Block Public Access settings: your responsibility."], "aws ssm describe-patch-baselines\naws rds describe-pending-maintenance-actions\naws s3api get-public-access-block --bucket <bucket>", "Get-SSMPatchBaseline\nGet-RDSPendingMaintenanceAction"),
  lab=dict(type="A", objective="Assign responsibilities correctly across services.", duration=10, steps=["Try each service with 'Patching the guest operating system' and 'Patching the database engine'.", "Try data encryption and physical security."], expected=["The split shifts with the service"], validation=[("aws-shared-correct", "Assigned correctly"), ("aws-shared-wrong", "Learned from a mistake")], failures=["Assuming AWS secures your S3 bucket policies"]),
  troubleshooting=[("Public S3 bucket leaked data.", "Customer misconfiguration (bucket policy/ACLs).", "Enable S3 Block Public Access and review policies."), ("Vulnerable OS on EC2.", "Guest OS patching is the customer's job.", "Use Systems Manager Patch Manager.")],
  comparisons=[("Azure shared responsibility", "Same model; Microsoft draws the split per IaaS/PaaS/SaaS.")],
  misconceptions=[("AWS is responsible for securing your data in S3.", "You control access and encryption choices."), ("RDS customers patch the database engine.", "AWS does; customers set the maintenance window.")],
  decisions=["Prefer managed services to shift operational security tasks to AWS."],
  docs=[("Shared responsibility model", SR), ("Security pillar: shared responsibility", D + "wellarchitected/latest/security-pillar/shared-responsibility.html"), ("Amazon RDS security", D + "AmazonRDS/latest/UserGuide/UsingWithRDS.html")])
for obj, s1, o1, s2, o2 in [
    ("2.1.1", "In the AWS shared responsibility model, what is AWS responsible for?", [("Security of the cloud", "Correct."), ("Security in the cloud", "Customer."), ("Customer data classification", "Customer."), ("IAM user passwords", "Customer.")],
     "A company asks who protects the physical servers running its EC2 instances. What is the answer?", [("AWS", "Correct."), ("The customer", "No."), ("Shared equally", "Physical security is AWS's."), ("The internet provider", "No.")]),
    ("2.1.2", "Which is a component of the shared responsibility model?", [("Shared controls such as patch management and configuration management", "Correct."), ("Shared root passwords", "Never share credentials."), ("Shared billing", "No."), ("Shared AZs", "No.")],
     "AWS patches the underlying hosts while the customer patches the EC2 guest OS. Which kind of control is patch management here?", [("A shared control", "Correct."), ("Inherited only", "Not entirely."), ("Customer-specific only", "AWS also patches infrastructure."), ("Not a control", "No.")]),
    ("2.1.3", "Which is the customer's responsibility on AWS?", [("Configuring security groups", "Correct."), ("Hypervisor security", "AWS."), ("Data center access control", "AWS."), ("Hardware disposal", "AWS.")],
     "An EC2-hosted app has a SQL injection flaw. Who is responsible for fixing it?", [("The customer", "Correct: application code."), ("AWS", "No."), ("Both equally", "No."), ("AWS Support", "No.")]),
    ("2.1.4", "Which is AWS's responsibility?", [("Maintaining the global network infrastructure", "Correct."), ("Managing IAM policies", "Customer."), ("Encrypting customer data", "Customer choice."), ("Patching EC2 guest OS", "Customer.")],
     "Who decommissions and destroys failed storage devices in AWS data centers?", [("AWS", "Correct."), ("The customer", "No."), ("A partner", "No."), ("Shared", "No.")]),
    ("2.1.5", "Which responsibility is shared between AWS and the customer?", [("Awareness and training", "Correct: each trains its own people."), ("Physical security", "AWS."), ("Customer data", "Customer."), ("Hypervisor patching", "AWS.")],
     "Configuration management is described as shared. What does the customer configure?", [("Their guest operating systems, databases and applications", "Correct."), ("AWS hardware", "AWS."), ("Data center cooling", "AWS."), ("Edge locations", "AWS.")]),
    ("2.1.6", "Who patches the database engine for Amazon RDS?", [("AWS", "Correct."), ("The customer", "That is for databases on EC2."), ("Nobody", "No."), ("AWS Marketplace", "No.")],
     "Moving from a database on EC2 to Amazon RDS shifts which responsibility to AWS?", [("OS and database engine patching", "Correct."), ("Managing database users", "Still customer."), ("Encrypting data choices", "Still customer."), ("Network access rules", "Still customer.")]),
]:
    qa(f"CLFC02-{obj}", 1, "single", s1, o1, "a", "AWS: security of the cloud; customer: security in the cloud.", SR)
    qa(f"CLFC02-{obj}", 2, "scenario", s2, o2, "a", "Responsibilities depend on the service model.", SR)

# ---------------------------------------------------------------- 2.2
L(id="clf-security-compliance", title="Security, governance and compliance concepts on AWS", objectives=ids("2.2", 9), minutes=45,
  objective="Describe AWS compliance and governance concepts, encryption options, where security logs live, where to find compliance information, and the services that monitor, audit and protect resources.",
  prereqs=[("Shared responsibility", "CLFC02-2.1.1", "clf-shared-responsibility")],
  foundation=["AWS follows many compliance programs (such as ISO 27001, SOC, PCI DSS, HIPAA eligibility). You download AWS's audit reports from AWS Artifact.", "Encryption protects data at rest (stored) and in transit (moving).",
              "Logs show what happened: AWS CloudTrail records API activity, Amazon CloudWatch collects metrics and logs, AWS Config records resource configuration."],
  engineer=["Compliance: AWS Compliance programs by industry and geography (for example GDPR, HIPAA, FedRAMP, C5); compliance is shared, and not every service is in scope for every program (check AWS Services in Scope by Compliance Program). AWS Artifact gives on-demand reports (SOC, PCI) and agreements (BAA). AWS Audit Manager helps collect evidence.",
            "Encryption: at rest with AWS KMS keys (AWS managed or customer managed) or CloudHSM; in transit with TLS (AWS Certificate Manager for certificates). Many services support server-side encryption, and S3 encrypts new objects by default (SSE-S3).",
            "Logs: CloudTrail (management and data events; trail to S3; CloudTrail Lake), CloudWatch Logs and metrics, VPC Flow Logs, AWS Config history, S3 server access logs, ELB access logs.",
            "Protect and detect: Amazon Inspector (vulnerabilities), Amazon GuardDuty (threat detection), AWS Security Hub (aggregated findings and standards), AWS Shield (DDoS), AWS WAF, Amazon Macie (sensitive data in S3), Amazon Detective (investigation).",
            "Governance and compliance services: CloudWatch (monitoring), CloudTrail and AWS Config (auditing), IAM access reports (access advisor, credential reports), AWS Organizations SCPs, AWS Control Tower (governed multi-account landing zone)."],
  anim=("aws-security-sim", "Open 'Security services' and match needs to services."),
  diagram=([("res", "AWS resources", 0, 60, "compute"), ("ct", "CloudTrail (API audit)", 230, 0, "storage"), ("cfg", "AWS Config (configuration)", 230, 120, "storage"), ("gd", "GuardDuty / Inspector / Macie", 460, 0, "security"), ("sh", "Security Hub", 690, 60, "security"), ("art", "AWS Artifact (reports)", 460, 180, "service")],
           [("res", "ct"), ("res", "cfg"), ("ct", "gd"), ("gd", "sh"), ("cfg", "sh")]),
  example=("Preparing for a PCI audit", ["The team downloads AWS's PCI DSS Attestation of Compliance from Artifact, confirms that the services used are in scope, enables CloudTrail in all Regions with log file validation, uses AWS Config conformance packs, encrypts data with KMS, and reviews findings in Security Hub."]),
  config=cfg(["AWS Artifact > Reports.", "CloudTrail > Trails > Create trail.", "Security Hub > Enable; GuardDuty > Enable."], "aws cloudtrail create-trail --name org-trail --s3-bucket-name <bucket> --is-multi-region-trail\naws guardduty create-detector --enable\naws securityhub enable-security-hub\naws kms create-key --description app-key", "New-CTTrail -Name org-trail -S3BucketName <bucket> -IsMultiRegionTrail $true\nNew-GDDetector -Enable $true"),
  lab=clab("aws-sec-service", "Security services", "security service"),
  troubleshooting=[("Cannot tell who changed a security group.", "CloudTrail not reviewed or not enabled for that Region.", "Use CloudTrail event history and a multi-Region trail."), ("Auditor needs AWS's SOC report.", "Not available in the console you checked.", "Download it from AWS Artifact.")],
  comparisons=[("Microsoft Purview / Defender for Cloud / Service Trust Portal", "Azure equivalents for compliance reports and security posture.")],
  misconceptions=[("Using a compliant service makes your workload compliant.", "Compliance is shared; you must configure it correctly."), ("CloudWatch records who called an API.", "CloudTrail does.")],
  decisions=["Turn on CloudTrail, Config, GuardDuty and Security Hub across all accounts from day one (Control Tower can do this)."],
  docs=[("AWS Compliance programs", A + "compliance/programs/"), ("AWS Artifact", D + "artifact/latest/ug/what-is-aws-artifact.html"), ("AWS services in scope by compliance program", A + "compliance/services-in-scope/"),
        ("AWS CloudTrail", D + "awscloudtrail/latest/userguide/cloudtrail-user-guide.html"), ("AWS Config", D + "config/latest/developerguide/WhatIsConfig.html"), ("AWS KMS", D + "kms/latest/developerguide/overview.html"), ("Amazon GuardDuty", D + "guardduty/latest/ug/what-is-guardduty.html")])
for obj, s1, o1, s2, o2, doc in [
    ("2.2.1", "Which statement about compliance on AWS is true?", [("AWS provides compliant infrastructure, but customers are responsible for configuring their workloads compliantly", "Correct."), ("Any workload on AWS is automatically compliant", "No."), ("AWS has no compliance programs", "No."), ("Compliance is only the customer's job", "Shared.")],
     "A company must enforce that no account in its organisation can disable CloudTrail. Which governance feature helps?", [("Service control policies in AWS Organizations", "Correct."), ("Amazon Polly", "No."), ("S3 lifecycle rules", "No."), ("Amazon Lightsail", "No.")], D + "organizations/latest/userguide/orgs_manage_policies_scps.html"),
    ("2.2.2", "Which is a benefit of encryption in the cloud?", [("Data is unreadable without the keys, protecting it at rest and in transit", "Correct."), ("It removes the need for IAM", "No."), ("It increases storage size", "Not a benefit."), ("It disables logging", "No.")],
     "A company wants control over encryption keys used by S3, EBS and RDS, with audit logs of key use. What should it use?", [("AWS KMS customer managed keys", "Correct."), ("AWS Artifact", "No."), ("Amazon Inspector", "No."), ("Route 53", "No.")], D + "kms/latest/developerguide/overview.html"),
    ("2.2.3", "Where are API calls made in an AWS account recorded?", [("AWS CloudTrail", "Correct."), ("Amazon CloudFront", "CDN."), ("AWS Artifact", "Reports."), ("Amazon Lex", "Chatbots.")],
     "Security wants network traffic metadata (source/destination IPs, ports, accept/reject) for a VPC. What should be enabled?", [("VPC Flow Logs", "Correct."), ("CloudTrail data events", "API-level, not packet metadata."), ("AWS Budgets", "No."), ("AWS Backup", "No.")], D + "vpc/latest/userguide/flow-logs.html"),
    ("2.2.4", "Where can customers download AWS SOC and PCI compliance reports?", [("AWS Artifact", "Correct."), ("AWS Trusted Advisor", "Best-practice checks."), ("Amazon Inspector", "Vulnerabilities."), ("AWS Support Center", "Support cases.")],
     "An auditor asks for AWS's ISO 27001 certification. What do you do?", [("Download it from AWS Artifact", "Correct."), ("Open a support case to request hardware access", "Not available."), ("Run Amazon Inspector", "No."), ("Use AWS Config", "No.")], D + "artifact/latest/ug/what-is-aws-artifact.html"),
    ("2.2.5", "Why do compliance needs differ by location or industry?", [("Laws and regulations (for example GDPR in the EU, HIPAA for US healthcare) vary", "Correct."), ("AWS prices vary", "Not compliance."), ("Regions have different instance types", "Not the reason."), ("Edge locations require it", "No.")],
     "A healthcare company in the US must store protected health information. What must it check?", [("That it uses HIPAA-eligible services and signs a BAA via AWS Artifact", "Correct."), ("That it uses Spot Instances", "Unrelated."), ("That it uses only us-east-1", "Not required."), ("That it disables encryption", "No.")], A + "compliance/hipaa-compliance/"),
    ("2.2.6", "Which service scans EC2 instances and container images for software vulnerabilities?", [("Amazon Inspector", "Correct."), ("Amazon GuardDuty", "Threat detection."), ("AWS Shield", "DDoS."), ("Amazon Macie", "Sensitive data in S3.")],
     "Security wants continuous threat detection that analyses CloudTrail, VPC Flow Logs and DNS logs without deploying agents. Which service?", [("Amazon GuardDuty", "Correct."), ("Amazon Inspector", "Vulnerability scanning."), ("AWS WAF", "Web requests."), ("AWS Artifact", "Reports.")], D + "guardduty/latest/ug/what-is-guardduty.html"),
    ("2.2.7", "Which is an example of encryption in transit?", [("HTTPS (TLS) between clients and an Application Load Balancer", "Correct."), ("SSE-KMS on S3 objects", "At rest."), ("Encrypted EBS volumes", "At rest."), ("RDS storage encryption", "At rest.")],
     "Data on EBS volumes must be encrypted with keys you manage. What do you enable?", [("EBS encryption with a customer managed KMS key", "Correct."), ("TLS on the load balancer", "In transit only."), ("CloudFront", "No."), ("IAM MFA", "Authentication.")], D + "ebs/latest/userguide/ebs-encryption.html"),
    ("2.2.8", "Which service audits configuration changes to resources over time and evaluates them against rules?", [("AWS Config", "Correct."), ("Amazon CloudWatch", "Metrics and logs."), ("AWS CloudTrail", "API calls."), ("AWS Artifact", "Reports.")],
     "Which combination supports governance: monitoring, auditing API activity and tracking configuration?", [("CloudWatch, CloudTrail and AWS Config", "Correct."), ("Polly, Lex and Translate", "AI services."), ("S3, EBS and EFS", "Storage."), ("Lightsail and Amplify", "No.")], D + "config/latest/developerguide/WhatIsConfig.html"),
    ("2.2.9", "Why must you check which services are in scope for a compliance program?", [("Not every AWS service is in scope for every program", "Correct."), ("All services are always in scope", "No."), ("Only paid services are compliant", "No."), ("Scope changes by instance size", "No.")],
     "A PCI workload needs a new AWS service. What should you verify first?", [("That the service is listed as in scope for PCI DSS", "Correct."), ("That it supports Spot pricing", "Unrelated."), ("That it has a free tier", "Unrelated."), ("That it runs in every Region", "Unrelated.")], A + "compliance/services-in-scope/"),
]:
    qa(f"CLFC02-{obj}", 1, "single", s1, o1, "a", "See the lesson for details.", doc)
    qa(f"CLFC02-{obj}", 2, "scenario", s2, o2, "a", "Applied security and compliance.", doc)

# ---------------------------------------------------------------- 2.3
L(id="clf-access-management", title="AWS access management: IAM, root user, Identity Center and credentials", objectives=ids("2.3", 10), minutes=50,
  objective="Explain IAM users, groups, roles and policies, least privilege, root user protection and root-only tasks, IAM Identity Center and federation, MFA, access keys, password policies and credential storage.",
  prereqs=[("Shared responsibility", "CLFC02-2.1.3", "clf-shared-responsibility")],
  foundation=["AWS Identity and Access Management (IAM) controls who can sign in (authentication) and what they can do (authorization) in your AWS account.", "The root user is the email account that created the AWS account. It has full power, so protect it with MFA and use it only for the few tasks that require it.",
              "Give people only the permissions they need (least privilege), preferably through groups and roles, and sign in through IAM Identity Center."],
  engineer=["IAM entities: users (long-term credentials; minimise), groups (collections of users; attach policies), roles (temporary credentials assumed by users, services or other accounts), policies (JSON: Effect, Action, Resource, Condition). AWS managed policies vs customer managed policies vs inline policies.",
            "Evaluation: explicit Deny wins; otherwise an explicit Allow is needed; everything else is implicitly denied. SCPs in AWS Organizations set the maximum permissions for member accounts (including their root user).",
            "Root user: enable MFA, do not create root access keys, use for root-only tasks such as changing account settings (name, email, root password), closing the account, restoring IAM permissions when locked out, configuring S3 MFA delete, and registering as a seller in the Reserved Instance Marketplace.",
            "Authentication: passwords with an IAM password policy, MFA (virtual authenticator, FIDO security keys, hardware TOTP), access keys for programmatic access (rotate, avoid on root), temporary credentials via roles (STS).",
            "IAM Identity Center: central workforce access to multiple accounts and apps with permission sets, using its own directory or an external identity provider (federation with SAML/OIDC, for example Microsoft Entra ID or Okta). Cross-account roles grant access between accounts.",
            "Credential storage: AWS Secrets Manager (secrets with automatic rotation) and AWS Systems Manager Parameter Store (configuration and SecureString parameters)."],
  anim=("aws-security-sim", "Open 'IAM policy evaluation' and 'Root user tasks'."),
  diagram=([("idp", "Identity provider (Entra ID / Okta)", 0, 0, "identity"), ("ic", "IAM Identity Center (permission sets)", 250, 0, "identity"), ("role", "IAM role in account", 500, 0, "security"), ("grp", "IAM group → managed policy", 250, 140, "security"), ("res", "AWS resources", 750, 60, "storage"), ("root", "Root user (MFA, rarely used)", 500, 180, "user")],
           [("idp", "ic", "federation"), ("ic", "role", "temporary credentials"), ("role", "res"), ("grp", "res")]),
  example=("Hardening a new account", ["The founder enables MFA on the root user and stores its credentials securely. Staff sign in through IAM Identity Center federated with the company's identity provider, receiving permission sets such as ReadOnlyAccess or a custom least-privilege set. Apps on EC2 use IAM roles and read database passwords from Secrets Manager."]),
  config=cfg(["IAM > Dashboard: security recommendations (root MFA).", "IAM > Account settings: password policy.", "IAM Identity Center > Permission sets.", "Secrets Manager > Store a new secret."], "aws iam get-account-summary\naws iam update-account-password-policy --minimum-password-length 14 --require-symbols\naws iam create-group --group-name Developers && aws iam attach-group-policy --group-name Developers --policy-arn arn:aws:iam::aws:policy/ReadOnlyAccess\naws secretsmanager create-secret --name prod/db --secret-string '{\"password\":\"...\"}'",
      "Get-IAMAccountSummary\nNew-IAMGroup -GroupName Developers\nRegister-IAMGroupPolicy -GroupName Developers -PolicyArn arn:aws:iam::aws:policy/ReadOnlyAccess"),
  lab=dict(type="A", objective="Predict IAM decisions and identify root-only tasks.", duration=15, steps=["IAM policy evaluation: apply each preset.", "Root user tasks: answer every task."], expected=["Explicit deny wins; SCP limits even root"], validation=[("aws-iam-denied", "Saw a request denied"), ("aws-iam-allowed", "Saw a request allowed"), ("aws-root-correct", "Identified a root-only task")], failures=["Using root for daily work"]),
  troubleshooting=[("AccessDenied despite an Allow policy.", "An explicit Deny or SCP applies.", "Check SCPs and all attached policies."), ("Leaked access keys in a public repo.", "Long-term credentials exposed.", "Deactivate and rotate keys; prefer roles and temporary credentials.")],
  comparisons=[("Microsoft Entra ID + Azure RBAC", "Azure separates directory (Entra ID) from resource authorization (RBAC); AWS IAM covers both within an account.")],
  misconceptions=[("The root user should be used for administration.", "Use IAM Identity Center or IAM roles; root only for root tasks."), ("IAM roles have passwords.", "Roles provide temporary credentials.")],
  decisions=["Federate workforce access through IAM Identity Center; use roles for workloads; enforce MFA."],
  docs=[("What is IAM?", IAM), ("Tasks that require root user credentials", D + "IAM/latest/UserGuide/root-user-tasks.html"), ("IAM best practices", D + "IAM/latest/UserGuide/best-practices.html"),
        ("Policy evaluation logic", D + "IAM/latest/UserGuide/reference_policies_evaluation-logic.html"), ("IAM Identity Center", D + "singlesignon/latest/userguide/what-is.html"), ("AWS Secrets Manager", D + "secretsmanager/latest/userguide/intro.html")])
for obj, s1, o1, s2, o2, doc in [
    ("2.3.1", "Which IAM identity provides temporary credentials and can be assumed by services such as EC2?", [("IAM role", "Correct."), ("IAM user", "Long-term credentials."), ("IAM group", "Cannot sign in."), ("Root user", "No.")],
     "An application on EC2 must read from S3 without storing access keys. What should you use?", [("An IAM role attached to the instance (instance profile)", "Correct."), ("Root access keys in the code", "Never."), ("An IAM user's keys in a config file", "Avoid long-term keys."), ("A security group", "Network control.")], D + "IAM/latest/UserGuide/id_roles.html"),
    ("2.3.2", "Why must the root user be protected?", [("It has unrestricted access to all resources and billing in the account", "Correct."), ("It cannot be used", "It can."), ("It is shared by all users", "It must not be."), ("It is only for billing", "Full access.")],
     "What should you do first after creating a new AWS account?", [("Enable MFA on the root user and avoid using it day to day", "Correct."), ("Create root access keys", "Avoid."), ("Share the root password with admins", "Never."), ("Disable CloudTrail", "No.")], D + "IAM/latest/UserGuide/root-user-best-practices.html"),
    ("2.3.3", "What is the principle of least privilege?", [("Grant only the permissions required to perform a task", "Correct."), ("Grant admin to everyone", "No."), ("Deny everything forever", "No."), ("Use only root", "No.")],
     "A developer needs to read objects in one S3 bucket. Which policy follows least privilege?", [("Allow s3:GetObject on that bucket's objects only", "Correct."), ("AdministratorAccess", "Too broad."), ("AmazonS3FullAccess", "Too broad."), ("PowerUserAccess", "Too broad.")], D + "IAM/latest/UserGuide/best-practices.html"),
    ("2.3.4", "What is AWS IAM Identity Center used for?", [("Centrally managing workforce access to multiple AWS accounts and applications", "Correct."), ("Storing database passwords", "Secrets Manager."), ("DDoS protection", "Shield."), ("Encrypting data", "KMS.")],
     "Employees should sign in once with their corporate identity and access several AWS accounts. What do you set up?", [("IAM Identity Center federated with the corporate IdP", "Correct."), ("One IAM user per account per employee", "Hard to manage."), ("Shared root credentials", "Never."), ("AWS Artifact", "No.")], D + "singlesignon/latest/userguide/what-is.html"),
    ("2.3.5", "Which service stores database credentials and rotates them automatically?", [("AWS Secrets Manager", "Correct."), ("Amazon S3", "Not for secrets."), ("AWS Artifact", "No."), ("Amazon CloudWatch", "No.")],
     "Which practice applies to IAM access keys?", [("Rotate them regularly and never create them for the root user", "Correct."), ("Embed them in public code", "No."), ("Share one key across a team", "No."), ("Use them instead of roles for EC2", "Use roles.")], D + "secretsmanager/latest/userguide/intro.html"),
    ("2.3.6", "Which is an authentication method in AWS?", [("Multi-factor authentication (MFA)", "Correct."), ("Security groups", "Network."), ("S3 lifecycle", "Storage."), ("CloudFront", "CDN.")],
     "A team in Account A must manage resources in Account B without creating new users in B. What should be used?", [("A cross-account IAM role in Account B", "Correct."), ("Sharing Account B's root password", "Never."), ("Copying IAM users", "Not needed."), ("VPC peering", "Network only.")], D + "IAM/latest/UserGuide/tutorial_cross-account-with-roles.html"),
    ("2.3.7", "What is the advantage of attaching policies to IAM groups instead of users?", [("Permissions are managed once for everyone with the same job", "Correct."), ("Groups can sign in", "They cannot."), ("Groups bypass MFA", "No."), ("Groups are free while users cost money", "IAM is free.")],
     "You need a permission set that AWS managed policies don't cover exactly. What do you create?", [("A customer managed policy with only the needed actions", "Correct."), ("Use AdministratorAccess", "Too broad."), ("Use the root user", "No."), ("An SCP to grant it", "SCPs don't grant permissions.")], D + "IAM/latest/UserGuide/access_policies_managed-vs-inline.html"),
    ("2.3.8", "Which task can only be performed by the root user?", [("Closing the AWS account", "Correct."), ("Launching an EC2 instance", "IAM can."), ("Creating an S3 bucket", "IAM can."), ("Viewing CloudWatch metrics", "IAM can.")],
     "Which task requires the root user?", [("Changing the account's root email address", "Correct."), ("Creating IAM users", "IAM admins can."), ("Creating a VPC", "IAM can."), ("Attaching policies", "IAM can.")], D + "IAM/latest/UserGuide/root-user-tasks.html"),
    ("2.3.9", "Which method best protects the root user?", [("Enable MFA and store credentials securely, without root access keys", "Correct."), ("Share it among admins", "No."), ("Use it daily so it stays active", "No."), ("Attach a policy to restrict it in a standalone account", "Policies cannot be attached to root.")],
     "In AWS Organizations, how can you restrict actions of member accounts' root users?", [("Service control policies (SCPs)", "Correct."), ("IAM groups", "Cannot contain root."), ("Security groups", "Network."), ("AWS Budgets", "Cost.")], D + "IAM/latest/UserGuide/root-user-best-practices.html"),
    ("2.3.10", "What is identity federation?", [("Letting users sign in with an external identity provider instead of creating IAM users", "Correct."), ("Merging AWS accounts", "No."), ("Encrypting identities", "No."), ("Using one password for all users", "No.")],
     "A company uses Microsoft Entra ID for employees and wants them to access AWS without new passwords. Which approach?", [("Federate Entra ID with IAM Identity Center (SAML)", "Correct."), ("Create IAM users with the same passwords", "Duplicates identities."), ("Use root credentials", "No."), ("Use Amazon Cognito for workforce users", "Cognito is mainly for customer app users.")], D + "singlesignon/latest/userguide/manage-your-identity-source-idp.html"),
]:
    qa(f"CLFC02-{obj}", 1, "single", s1, o1, "a", "See the lesson for details.", doc)
    qa(f"CLFC02-{obj}", 2, "scenario", s2, o2, "a", "Applied access management.", doc)

# ---------------------------------------------------------------- 2.4
L(id="clf-security-resources", title="Security services, documentation and Marketplace security products", objectives=ids("2.4", 6), minutes=35,
  objective="Describe AWS security features and services (WAF, Firewall Manager, Shield, GuardDuty), where to find AWS security information, third-party security in AWS Marketplace, and Trusted Advisor for identifying issues.",
  prereqs=[("Security and compliance concepts", "CLFC02-2.2.6", "clf-security-compliance")],
  foundation=["AWS offers many built-in security services: firewalls for web apps (AWS WAF), DDoS protection (AWS Shield), threat detection (Amazon GuardDuty) and central firewall management (AWS Firewall Manager).",
              "AWS publishes security guidance on the AWS Security Center, the AWS Security Blog and the AWS Knowledge Center.", "You can also buy third-party security tools in AWS Marketplace, and AWS Trusted Advisor flags security risks such as open ports or missing MFA."],
  engineer=["AWS WAF: rules (managed rule groups, rate-based rules, IP sets) for CloudFront, ALB, API Gateway and AppSync. AWS Shield Standard: automatic DDoS protection at no extra cost; Shield Advanced: enhanced protection, cost protection and access to the Shield Response Team. AWS Firewall Manager: central policies for WAF, Shield Advanced, security groups, Network Firewall and DNS Firewall across an organisation.",
            "Detect and respond: GuardDuty (threat detection), Inspector, Macie, Security Hub, Detective; network security: security groups, NACLs, AWS Network Firewall.",
            "Security information: AWS Security Center (aws.amazon.com/security), AWS Security Blog, AWS Knowledge Center (on re:Post), security bulletins, whitepapers (for example AWS Security Best Practices), Well-Architected security pillar.",
            "AWS Marketplace: third-party firewalls, antivirus, SIEM and identity products, billed through your AWS account.",
            "Trusted Advisor security checks include S3 bucket permissions, security groups with unrestricted access, IAM use, MFA on root and exposed access keys; the full set of checks depends on the support plan."],
  anim=("aws-security-sim", "Open 'Security services' to match protection needs to services."),
  diagram=([("users", "Users / attackers", 0, 60, "user"), ("shield", "AWS Shield (DDoS)", 200, 60, "security"), ("waf", "AWS WAF (L7 rules)", 400, 60, "security"), ("alb", "CloudFront / ALB", 600, 60, "network"), ("fm", "Firewall Manager (central policies)", 400, 180, "security")], [("users", "shield"), ("shield", "waf"), ("waf", "alb"), ("fm", "waf")]),
  example=("Protecting a public web app", ["A media company fronts its site with CloudFront and AWS WAF managed rules, subscribes to Shield Advanced for DDoS response support, uses Firewall Manager to apply the same WAF rules to every account, and reviews Trusted Advisor security checks weekly."]),
  config=cfg(["WAF & Shield > Web ACLs > Create.", "Firewall Manager > Security policies.", "Trusted Advisor > Security.", "AWS Marketplace > Security category."], "aws wafv2 list-web-acls --scope CLOUDFRONT --region us-east-1\naws shield describe-subscription\naws support describe-trusted-advisor-checks --language en", "Get-WAF2WebACLList -Scope REGIONAL\nGet-ASATrustedAdvisorCheck -Language en"),
  lab=clab("aws-sec-service", "Security services", "security service"),
  troubleshooting=[("Site overwhelmed by a layer 7 flood.", "No WAF rate-based rules.", "Add AWS WAF rate-based rules; consider Shield Advanced."), ("Different accounts have inconsistent firewall rules.", "No central management.", "Use AWS Firewall Manager.")],
  comparisons=[("Azure WAF / DDoS Protection / Firewall Manager", "Equivalent Azure services.")],
  misconceptions=[("Shield Standard costs extra.", "Shield Standard is included at no additional cost."), ("WAF protects against network-layer DDoS.", "WAF is layer 7; Shield covers DDoS.")],
  decisions=["Combine CloudFront, WAF and Shield for internet-facing apps; manage centrally with Firewall Manager."],
  docs=[("AWS WAF", D + "waf/latest/developerguide/what-is-aws-waf.html"), ("AWS Shield", D + "waf/latest/developerguide/shield-chapter.html"), ("AWS Firewall Manager", D + "waf/latest/developerguide/fms-chapter.html"),
        ("AWS Security Blog", A + "blogs/security/"), ("AWS Knowledge Center", "https://repost.aws/knowledge-center"), ("AWS Trusted Advisor", D + "awssupport/latest/user/trusted-advisor.html"), ("AWS Marketplace security", A + "marketplace/solutions/security")])
for obj, s1, o1, s2, o2, doc in [
    ("2.4.1", "Which AWS service provides DDoS protection automatically to all customers at no extra cost?", [("AWS Shield Standard", "Correct."), ("AWS Shield Advanced", "Paid."), ("Amazon Macie", "Data discovery."), ("AWS Artifact", "Reports.")],
     "Which capability does AWS provide to filter malicious HTTP requests such as SQL injection?", [("AWS WAF", "Correct."), ("Security groups", "Ports/IPs only."), ("AWS Backup", "No."), ("Amazon SNS", "No.")], D + "waf/latest/developerguide/shield-chapter.html"),
    ("2.4.2", "Where can you find AWS security best practices and announcements?", [("AWS Security Center and the AWS Security Blog", "Correct."), ("AWS Budgets", "Costs."), ("Amazon Polly", "No."), ("AWS Batch", "No.")],
     "A team wants official whitepapers on AWS security best practices. Where should it look?", [("AWS Whitepapers and the Well-Architected security pillar", "Correct."), ("Random forums", "Not official."), ("Amazon WorkSpaces", "No."), ("Cost Explorer", "No.")], A + "security/"),
    ("2.4.3", "Which service centrally manages AWS WAF rules and security groups across all accounts in an organisation?", [("AWS Firewall Manager", "Correct."), ("Amazon GuardDuty", "Detection."), ("AWS Shield Standard", "DDoS."), ("Amazon Inspector", "Vulnerabilities.")],
     "A company wants DDoS cost protection and access to the AWS Shield Response Team. What should it buy?", [("AWS Shield Advanced", "Correct."), ("Shield Standard", "No response team."), ("AWS WAF only", "No DDoS response team."), ("Amazon Detective", "No.")], D + "waf/latest/developerguide/fms-chapter.html"),
    ("2.4.4", "Where can customers buy third-party security software that runs on AWS?", [("AWS Marketplace", "Correct."), ("AWS Artifact", "No."), ("AWS Support Center", "No."), ("Amazon S3", "No.")],
     "A company wants its existing vendor's next-generation firewall in a VPC, billed through AWS. What should it use?", [("AWS Marketplace", "Correct."), ("AWS Config", "No."), ("AWS Lambda", "No."), ("Amazon Lex", "No.")], D + "marketplace/latest/buyerguide/what-is-marketplace.html"),
    ("2.4.5", "Which site answers common customer questions, including security questions?", [("AWS Knowledge Center (on AWS re:Post)", "Correct."), ("AWS Budgets", "No."), ("Amazon Connect", "No."), ("AWS IoT Core", "No.")],
     "A developer wants to read about a newly announced AWS security feature. Where is it most likely published?", [("AWS Security Blog", "Correct."), ("AWS Pricing Calculator", "No."), ("Amazon Polly", "No."), ("AWS Health Dashboard", "Service events, not features.")], "https://repost.aws/knowledge-center"),
    ("2.4.6", "Which service checks your account for security issues such as open security groups and missing root MFA?", [("AWS Trusted Advisor", "Correct."), ("AWS Artifact", "No."), ("Amazon Polly", "No."), ("AWS Snowball", "No.")],
     "A small company wants an automated list of security improvements for its account. Which tool should it check first?", [("AWS Trusted Advisor security checks", "Correct."), ("AWS Cost Explorer", "Costs."), ("Amazon Rekognition", "No."), ("AWS CodeBuild", "No.")], D + "awssupport/latest/user/trusted-advisor.html"),
]:
    qa(f"CLFC02-{obj}", 1, "single", s1, o1, "a", "See the lesson for details.", doc)
    qa(f"CLFC02-{obj}", 2, "scenario", s2, o2, "a", "Applied security services.", doc)
